describe('Nested Row Expansion in Table List', () => {
  beforeEach(() => {
    cy.visit('/table-list');
  });

  it('should expand a row to show nested details and collapse it back', () => {
    // Verify table is visible
    cy.get('[data-testid="table-container"]').should('be.visible');

    // Get the first row
    cy.get('[data-testid="table-row-1"]').should('be.visible');

    // Verify initial state: no expanded details
    cy.get('[data-testid="nested-details-1"]').should('not.exist');

    // Click the expand button
    cy.get('[data-testid="expand-row-1"]').click();

    // Verify nested details are now visible
    cy.get('[data-testid="nested-details-1"]').should('be.visible');

    // Verify nested content is displayed
    cy.get('[data-testid="nested-detail-1-name"]').should('contain', 'John Doe');
    cy.get('[data-testid="nested-detail-1-email"]').should('contain', 'john.doe@example.com');

    // Click the expand button again to collapse
    cy.get('[data-testid="expand-row-1"]').click();

    // Verify nested details are hidden
    cy.get('[data-testid="nested-details-1"]').should('not.exist');

    // Verify row is still visible
    cy.get('[data-testid="table-row-1"]').should('be.visible');
  });

  it('should handle expanding multiple rows and collapse all at once', () => {
    // Get multiple rows
    cy.get('[data-testid="table-row-1"]').should('be.visible');
    cy.get('[data-testid="table-row-2"]').should('be.visible');

    // Expand first row
    cy.get('[data-testid="expand-row-1"]').click();
    cy.get('[data-testid="nested-details-1"]').should('be.visible');

    // Expand second row
    cy.get('[data-testid="expand-row-2"]').click();
    cy.get('[data-testid="nested-details-2"]').should('be.visible');

    // Verify both rows are expanded
    cy.get('[data-testid="nested-details-1"]').should('be.visible');
    cy.get('[data-testid="nested-details-2"]').should('be.visible');

    // Click the collapse button on the first row
    cy.get('[data-testid="collapse-row-1"]').click();

    // Verify first row is collapsed
    cy.get('[data-testid="nested-details-1"]').should('not.exist');

    // Verify second row is still expanded
    cy.get('[data-testid="nested-details-2"]').should('be.visible');

    // Click the collapse button on the second row
    cy.get('[data-testid="collapse-row-2"]').click();

    // Verify both rows are collapsed
    cy.get('[data-testid="nested-details-1"]').should('not.exist');
    cy.get('[data-testid="nested-details-2"]').should('not.exist');

    // Verify table rows are still visible
    cy.get('[data-testid="table-row-1"]').should('be.visible');
    cy.get('[data-testid="table-row-2"]').should('be.visible');
  });
});
